function chooseQuote(bytes) {
  let hasSingleQuote = false;
  let hasDoubleQuote = false;

  for (const value of bytes) {
    if (value === 0x27) {
      hasSingleQuote = true;
    } else if (value === 0x22) {
      hasDoubleQuote = true;
    }
  }

  return hasSingleQuote && !hasDoubleQuote ? '"' : "'";
}

function escapeByte(value, quote) {
  if (value === 0x5c) {
    return '\\\\';
  }

  if (value === 0x09) {
    return '\\t';
  }

  if (value === 0x0a) {
    return '\\n';
  }

  if (value === 0x0d) {
    return '\\r';
  }

  if (value === quote.charCodeAt(0)) {
    return `\\${quote}`;
  }

  if (value >= 0x20 && value <= 0x7e) {
    return String.fromCharCode(value);
  }

  return `\\x${value.toString(16).padStart(2, '0')}`;
}

export function formatPythonBytes(bytesLike) {
  const bytes = bytesLike instanceof Uint8Array ? bytesLike : Uint8Array.from(bytesLike);
  const quote = chooseQuote(bytes);
  let result = `b${quote}`;

  for (const value of bytes) {
    result += escapeByte(value, quote);
  }

  return `${result}${quote}`;
}

