export class CliUsageError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliUsageError';
    this.exitCode = 2;
  }
}

const LONG_OPTIONS = [
  { name: '--help', aliases: ['-h'], takesValue: false, dest: 'help' },
  { name: '--key', aliases: [], takesValue: true, dest: 'key' },
  { name: '--data', aliases: [], takesValue: true, dest: 'data' },
];

function resolveLongOption(token) {
  const exactMatch = LONG_OPTIONS.find((option) => option.name === token);

  if (exactMatch) {
    return exactMatch;
  }

  const matches = LONG_OPTIONS.filter((option) => option.name.startsWith(token));
  return matches.length === 1 ? matches[0] : null;
}

function looksLikeOptional(token) {
  return token !== undefined && token !== '-' && token.startsWith('-');
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test13.mjs';
  }

  const normalized = scriptPath.replace(/\\/g, '/');
  const lastSlash = normalized.lastIndexOf('/');
  return lastSlash === -1 ? normalized : normalized.slice(lastSlash + 1);
}

export function formatHelp(prog) {
  return `usage: ${prog} [-h] --key KEY --data DATA\n\noptions:\n  -h, --help   show this help message and exit\n  --key KEY\n  --data DATA\n`;
}

export function formatUsageError(prog, message) {
  return `usage: ${prog} [-h] --key KEY --data DATA\n${prog}: error: ${message}\n`;
}

export function parseCommandLine(argv) {
  const values = {};
  const extras = [];
  let endOfOptions = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      endOfOptions = true;
      continue;
    }

    if (token === '-h') {
      return { helpRequested: true };
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = resolveLongOption(optionToken);

      if (!option) {
        extras.push(token);
        continue;
      }

      if (option.dest === 'help') {
        if (equalsIndex !== -1) {
          const explicitArgument = token.slice(equalsIndex + 1);
          throw new CliUsageError(`argument -h/--help: ignored explicit argument '${explicitArgument}'`);
        }

        return { helpRequested: true };
      }

      if (equalsIndex !== -1) {
        values[option.dest] = token.slice(equalsIndex + 1);
        continue;
      }

      const nextToken = argv[index + 1];
      if (nextToken === undefined || looksLikeOptional(nextToken)) {
        throw new CliUsageError(`argument ${option.name}: expected one argument`);
      }

      values[option.dest] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (values.key === undefined) {
    missing.push('--key');
  }

  if (values.data === undefined) {
    missing.push('--data');
  }

  if (missing.length > 0) {
    throw new CliUsageError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new CliUsageError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { helpRequested: false, values };
}

