import { AESModeOfOperationECB } from './lib/aes/ecb.mjs';
import { formatHelp, formatUsageError, getProgramName, parseCommandLine, CliUsageError } from './lib/cli.mjs';
import { ValueError } from './lib/errors.mjs';
import { formatPythonBytes } from './lib/python_bytes.mjs';

function encodeUtf8(value) {
  return Uint8Array.from(Buffer.from(value, 'utf8'));
}

function writeStdoutLine(value) {
  process.stdout.write(`${value}\n`);
}

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const programName = getProgramName(scriptPath);

  try {
    const parsed = parseCommandLine(argv);

    if (parsed.helpRequested) {
      process.stdout.write(formatHelp(programName));
      return 0;
    }

    const aes = new AESModeOfOperationECB(encodeUtf8(parsed.values.key));
    const ciphertext = aes.encrypt(encodeUtf8(parsed.values.data));
    const plaintext = aes.decrypt(ciphertext);

    writeStdoutLine(formatPythonBytes(ciphertext));
    writeStdoutLine(formatPythonBytes(plaintext));
    return 0;
  } catch (error) {
    if (error instanceof CliUsageError) {
      process.stderr.write(formatUsageError(programName, error.message));
      return error.exitCode;
    }

    if (error instanceof ValueError) {
      process.stderr.write(`${error.name}: ${error.message}\n`);
      return 1;
    }

    throw error;
  }
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

